def comps(g,col=None):
    seen=set(); cs=[]; h=len(g); w=len(g[0])
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0 and (i,j) not in seen:
                st=[(i,j)]; cells=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and g[x][y]==g[a][b] and (x,y) not in seen: st.append((x,y))
                cs.append(cells)
    return cs
def solve(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cs=comps(g)
    # rightmost-first order by max col
    cs.sort(key=lambda c:-max(j for _,j in c))
    occ=[[False]*w for _ in range(h)]
    for c in cs:
        col=g[c[0][0]][c[0][1]]
        d=0
        while True:
            d2=d+1
            if any(j+d2>=w for i,j in c) or any(occ[i][j+d2] for i,j in c): break
            d=d2
        newcells=[(i,j+d) for i,j in c]
        for i,j in newcells: occ[i][j]=True
        for i,j in c: g[i][j]=0
        for i,j in newcells: g[i][j]=col
    return g
